CREATE TABLE IF NOT EXISTS post_media (post_id BIGINT UNSIGNED NOT NULL, media_id BIGINT UNSIGNED NOT NULL, sort_order INT NOT NULL DEFAULT 0, PRIMARY KEY(post_id, media_id), INDEX(media_id));
CREATE TABLE IF NOT EXISTS home_section_presets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `key` VARCHAR(80) NOT NULL UNIQUE, label VARCHAR(120) NOT NULL, type VARCHAR(80) NOT NULL, enabled TINYINT(1) NOT NULL DEFAULT 1, sort_order INT NOT NULL DEFAULT 0, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL);
